    address farmingToken;
    uint256 totalAmount;
    uint24 fee;
    int24 tickLower; // price ?
    int24 tickUpper; // price ?
    uint256 amount0Min;
    uint256 amount1Min;
    bytes swapPath;
}

contract PancakeswapV3StrategyAddBaseTokenOnlyWithCalculate is
    IStrategy,
    IERC721Receiver,
