            revert NotAuthorized();
        }

        if (_userFund) {
            IUserVault(msg.sender).requestFundsFromUser(
                params.baseToken,
                params.totalAmount
            );
        } else {
            IUserVault(msg.sender).requestFunds(
                params.baseToken,
                params.totalAmount
            );
        }

        address poolAddr = IUniswapV3Factory(factory).getPool(
            params.baseToken,
            params.farmingToken,
            params.fee
        );
        // todo: check poolAddr is zero

        // token1/token0
        (uint160 sqrtPriceX96, , , , , , ) = IUniswapV3Pool(poolAddr).slot0();
        uint160 sqrtPriceLowerX96 = TickMath.getSqrtRatioAtTick(
            params.tickLower
        );
        uint160 sqrtPriceUpperX96 = TickMath.getSqrtRatioAtTick(
            params.tickUpper
        );

        address token0Addr = IUniswapV3Pool(poolAddr).token0();
        uint256 swapAmount;
        address token1Addr;
        if (params.baseToken == token0Addr) {
            token1Addr = params.farmingToken;
            swapAmount = LiqMath.getToken0SwapAmount(
                sqrtPriceX96,
                sqrtPriceLowerX96,
                sqrtPriceUpperX96,
                params.totalAmount
            );
        } else {
            token1Addr = params.baseToken;
            swapAmount = LiqMath.getToken1SwapAmount(
                sqrtPriceX96,
                sqrtPriceLowerX96,
                sqrtPriceUpperX96,
                params.totalAmount
            );
        }

        SafeERC20.safeIncreaseAllowance(
            IERC20(params.baseToken),
            router,
            swapAmount
        );
        uint256 baseAmount = params.totalAmount - swapAmount;
        uint256 farmingAmount = IV3SwapRouter(router).exactInput(
            IV3SwapRouter.ExactInputParams(
                params.swapPath,
                address(this),
                swapAmount,
                0
            )
        );

        INonfungiblePositionManager.MintParams
            memory mintParams = INonfungiblePositionManager.MintParams(
                token0Addr,
                token1Addr,
                params.fee,
                params.tickLower,
                params.tickUpper,
                params.baseToken == token0Addr ? baseAmount : farmingAmount,
                params.baseToken == token0Addr ? farmingAmount : baseAmount,
                params.amount0Min,
                params.amount1Min,
                address(msg.sender),
                block.timestamp
            );

        SafeERC20.safeIncreaseAllowance(
            IERC20(mintParams.token0),
            positionManager,
            mintParams.amount0Desired
        );
        SafeERC20.safeIncreaseAllowance(
            IERC20(mintParams.token1),
            positionManager,
            mintParams.amount1Desired
        );

        (uint256 tokenID, , , ) = INonfungiblePositionManager(positionManager)
            .mint(mintParams);

        // There may be tokens left in this contract
        // We should return them to the fund source
        address refundAddr = _userFund
            ? IUserVault(msg.sender).user()
            : msg.sender;
        SafeERC20.safeTransfer(
            IERC20(params.baseToken),
            refundAddr,
            IERC20(params.baseToken).balanceOf(address(this))
        );
        SafeERC20.safeTransfer(
            IERC20(params.farmingToken),
            refundAddr,
            IERC20(params.farmingToken).balanceOf(address(this))
        );

        emit PCSV3AddBaseTokenOnly(
            tokenID,
            params.baseToken,
            params.farmingToken,
            baseAmount,
            farmingAmount
        );

        return (
            uint8(PositionType.V3_LP),
            abi.encode(
                V3Position({
                    tokenId: tokenID,
                    token0: params.baseToken,
